import{_ as e,o as a,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"MythicMobs Integration","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/mythic.md","filePath":"en/modules/attribute/mythic.md","lastUpdated":null}'),s={name:"en/modules/attribute/mythic.md"};function o(r,t,n,c,l,h){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="mythicmobs-integration" tabindex="-1">MythicMobs Integration <a class="header-anchor" href="#mythicmobs-integration" aria-label="Permalink to &quot;MythicMobs Integration&quot;">​</a></h1><p>EmakiAttribute integrates with MythicMobs for attribute damage mechanics, attribute conditions, and mob attribute configuration.</p><blockquote><p>MythicMobs is a soft dependency. If it is not installed, related features are skipped.</p></blockquote><h2 id="skill-mechanic-emaki-damage" tabindex="-1">Skill mechanic: <code>emaki_damage</code> <a class="header-anchor" href="#skill-mechanic-emaki-damage" aria-label="Permalink to &quot;Skill mechanic: \`emaki_damage\`&quot;">​</a></h2><p>Aliases: <code>emakiattribute_damage</code>, <code>attribute_damage</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>damage</code></td><td>double</td><td>skill power</td><td>Base damage.</td></tr><tr><td><code>damage_type</code></td><td>string</td><td>—</td><td>Damage type id, such as <code>physical</code> or <code>spell</code>.</td></tr><tr><td><code>allow_critical</code></td><td>boolean</td><td><code>true</code></td><td>Whether critical hits are allowed.</td></tr><tr><td><code>allow_target_dodge</code></td><td>boolean</td><td><code>false</code></td><td>Whether target dodge is allowed.</td></tr><tr><td><code>calculate_target_defense</code></td><td>boolean</td><td><code>true</code></td><td>Whether target defense is calculated.</td></tr><tr><td><code>trigger_mythic_on_damaged</code></td><td>boolean</td><td><code>false</code></td><td>Whether MythicMobs on-damaged behavior is triggered.</td></tr></tbody></table><p>Example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FireBlast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_damage{damage=50;damage_type=spell;allow_critical=true} @target</span></span></code></pre></div><h2 id="skill-mechanics-temporary-attributes" tabindex="-1">Skill mechanics: temporary attributes <a class="header-anchor" href="#skill-mechanics-temporary-attributes" aria-label="Permalink to &quot;Skill mechanics: temporary attributes&quot;">​</a></h2><p>These mechanics target skill targets (<code>@target</code>, <code>@self</code>, etc.) and work on both <strong>players and mobs</strong>. Temporary attributes are removed automatically on expiry and are not persisted (they are lost on restart).</p><h3 id="emaki-attribute-add" tabindex="-1"><code>emaki_attribute_add</code> <a class="header-anchor" href="#emaki-attribute-add" aria-label="Permalink to &quot;\`emaki_attribute_add\`&quot;">​</a></h3><p>Alias: <code>emakiattribute_add</code>. Adds one temporary attribute to the target.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>string</td><td>—</td><td>Temporary effect id. Re-applying the same id follows the stack mode.</td></tr><tr><td><code>attribute</code></td><td>string</td><td>—</td><td>Attribute id.</td></tr><tr><td><code>value</code></td><td>double</td><td><code>0</code></td><td>Temporary value.</td></tr><tr><td><code>duration</code></td><td>int</td><td>—</td><td>Duration in ticks, must be greater than 0.</td></tr><tr><td><code>stack_mode</code></td><td>string</td><td>attribute default</td><td><code>REPLACE</code> or <code>STACK</code>. Falls back to the attribute&#39;s <code>temporary_stack_mode</code>.</td></tr><tr><td><code>set</code></td><td>boolean</td><td><code>false</code></td><td>When <code>true</code>, uses overwrite (SET) instead of additive (ADD).</td></tr></tbody></table><h3 id="emaki-attribute-remove" tabindex="-1"><code>emaki_attribute_remove</code> <a class="header-anchor" href="#emaki-attribute-remove" aria-label="Permalink to &quot;\`emaki_attribute_remove\`&quot;">​</a></h3><p>Alias: <code>emakiattribute_remove</code>. Removes the temporary attribute with the given <code>effect_id</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>string</td><td>Temporary effect id to remove.</td></tr></tbody></table><h3 id="emaki-attribute-add-tag" tabindex="-1"><code>emaki_attribute_add_tag</code> <a class="header-anchor" href="#emaki-attribute-add-tag" aria-label="Permalink to &quot;\`emaki_attribute_add_tag\`&quot;">​</a></h3><p>Alias: <code>emakiattribute_add_tag</code>. Adds a temporary attribute for every attribute whose <code>tags</code> contain the given tag. Each attribute gets its own effect id (<code>prefix:attributeId</code>) so they never overwrite each other.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>string</td><td>—</td><td>Attribute tag (e.g. <code>DEBUFF</code>), case-insensitive.</td></tr><tr><td><code>value</code></td><td>double</td><td><code>0</code></td><td>Value applied to every matching attribute.</td></tr><tr><td><code>duration</code></td><td>int</td><td>—</td><td>Duration in ticks, must be greater than 0.</td></tr><tr><td><code>effect_prefix</code></td><td>string</td><td><code>tag:&lt;tag&gt;</code></td><td>Prefix for the generated effect ids.</td></tr><tr><td><code>stack_mode</code></td><td>string</td><td>per-attribute default</td><td><code>REPLACE</code> or <code>STACK</code>. Falls back to each attribute&#39;s <code>temporary_stack_mode</code>.</td></tr></tbody></table><h3 id="emaki-attribute-clear-tag" tabindex="-1"><code>emaki_attribute_clear_tag</code> <a class="header-anchor" href="#emaki-attribute-clear-tag" aria-label="Permalink to &quot;\`emaki_attribute_clear_tag\`&quot;">​</a></h3><p>Alias: <code>emakiattribute_clear_tag</code>. Clears every temporary attribute whose attribute carries the given tag.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>string</td><td>Attribute tag, case-insensitive.</td></tr></tbody></table><p>Example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CurseStrike</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_add{effect_id=curse_slow;attribute=movement_speed;value=-2;duration=100} @target</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_add_tag{tag=DEBUFF;value=-10;duration=100;stack_mode=STACK} @target</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Purify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_clear_tag{tag=DEBUFF} @target</span></span></code></pre></div><h2 id="condition-emaki-attribute" tabindex="-1">Condition: <code>emaki_attribute</code> <a class="header-anchor" href="#condition-emaki-attribute" aria-label="Permalink to &quot;Condition: \`emaki_attribute\`&quot;">​</a></h2><p>Aliases: <code>emakiattribute_attribute</code>, <code>attribute_value</code>, <code>attribute_resource</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>attribute</code></td><td>Attribute id when checking an attribute value.</td></tr><tr><td><code>resource</code></td><td>Resource id when checking a resource value. Players only.</td></tr><tr><td><code>field</code></td><td>Resource field: <code>current</code> (aliases <code>current_value</code>, <code>value</code>), <code>max</code> (alias <code>current_max</code>), <code>default</code> (alias <code>default_max</code>), <code>bonus</code> (alias <code>bonus_max</code>), or <code>percent</code>. Defaults to <code>current</code>.</td></tr><tr><td><code>operator</code></td><td>Comparison operator.</td></tr><tr><td><code>value</code></td><td>Comparison value.</td></tr><tr><td><code>value_2</code></td><td>Second value for <code>between</code>.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Operator</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>&gt;</code></td><td><code>gt</code></td><td>Greater than.</td></tr><tr><td><code>&gt;=</code></td><td><code>gte</code></td><td>Greater than or equal (default).</td></tr><tr><td><code>&lt;</code></td><td><code>lt</code></td><td>Less than.</td></tr><tr><td><code>&lt;=</code></td><td><code>lte</code></td><td>Less than or equal.</td></tr><tr><td><code>!=</code></td><td><code>&lt;&gt;</code>, <code>ne</code></td><td>Not equal.</td></tr><tr><td><code>between</code></td><td>—</td><td>Between <code>value</code> and <code>value_2</code>, inclusive and order-independent.</td></tr></tbody></table><blockquote><p>Omitting <code>operator</code> or supplying an unrecognized one falls back to <code>&gt;=</code>. There is no dedicated equality operator.</p></blockquote><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Conditions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute{resource=health;field=percent;operator=&lt;;value=30} true</span></span></code></pre></div><h2 id="mob-attributes" tabindex="-1">Mob attributes <a class="header-anchor" href="#mob-attributes" aria-label="Permalink to &quot;Mob attributes&quot;">​</a></h2><p>MythicMobs mobs can define an <code>EmakiAttribute</code> section:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FireDragon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENDER_DRAGON</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Health</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  EmakiAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_attack: 100&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_defense: 50&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spell_attack: 80&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;health: 500&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Every entry must be quoted</p><p><code>EmakiAttribute</code> is a string list. Written unquoted as <code>- physical_attack: 100</code>, YAML parses each entry as a mapping instead of a string, the whole section is skipped, the mob receives no attributes, and nothing is logged.</p><p>To check: run <code>/ea debug on</code> and enter combat, then look for your attribute IDs in the attacker snapshot. Seeing only <code>default_profile</code> entries means the section was not read.</p></div><p>Attributes are synchronized when Mythic mobs spawn, and active Mythic mobs are resynced after MythicMobs reloads.</p>`,35)])])}const u=e(s,[["render",o]]);export{k as __pageData,u as default};
